import heapq


class Solution:
    def maxProfit(self, inventory: List[int], orders: int) -> int:
        MOD = 10 ** 9 + 7
        heap = [-x for x in inventory]
        heapq.heapify(heap)
        ans = 0
        for _ in range(orders):
            x = -heapq.heappop(heap)
            ans = (ans + x) % MOD
            if x > 1:
                heapq.heappush(heap, -(x - 1))
        return ans

