class Solution {
public:
    int maxProfit(vector<int>& inventory, int orders) {
        priority_queue<int> pq(inventory.begin(), inventory.end());
        const long long MOD = 1e9 + 7;
        long long ans = 0;
        while (orders-- > 0) {
            long long x = pq.top();
            pq.pop();
            ans = (ans + x) % MOD;
            if (x > 1) pq.push(x - 1);
        }
        return (int)ans;
    }
};

