class Solution {
    public int maxProfit(int[] inventory, int orders) {
        PriorityQueue<Integer> pq = new PriorityQueue<>(Collections.reverseOrder());
        for (int x : inventory) pq.offer(x);
        final long MOD = 1000000007L;
        long ans = 0;
        while (orders-- > 0) {
            long x = pq.poll();
            ans = (ans + x) % MOD;
            if (x > 1) pq.offer((int) x - 1);
        }
        return (int) ans;
    }
}

