var maxProfit = function(inventory, orders) {
    const MOD = 1000000007;
    const heap = [...inventory];
    const siftUp = (i) => {
        while (i > 0) {
            const p = (i - 1) >> 1;
            if (heap[p] >= heap[i]) break;
            [heap[p], heap[i]] = [heap[i], heap[p]];
            i = p;
        }
    };
    const siftDown = () => {
        let i = 0;
        for (;;) {
            const l = 2 * i + 1, r = l + 1;
            let big = i;
            if (l < heap.length && heap[l] > heap[big]) big = l;
            if (r < heap.length && heap[r] > heap[big]) big = r;
            if (big === i) break;
            [heap[big], heap[i]] = [heap[i], heap[big]];
            i = big;
        }
    };
    for (let i = 0; i < heap.length; i++) siftUp(i);
    let ans = 0;
    while (orders-- > 0) {
        const x = heap[0];
        ans = (ans + x) % MOD;
        heap[0] = x - 1;
        siftDown();
    }
    return ans;
};

