class Solution {
    static constexpr long long MOD = 1e9 + 7;

    static long long seriesSum(long long hi, long long lo) {
        long long cnt = hi - lo + 1;
        long long s = hi + lo;
        if (cnt % 2 == 0) cnt /= 2;
        else s /= 2;
        return cnt % MOD * (s % MOD) % MOD;
    }

public:
    int maxProfit(vector<int>& inventory, int orders) {
        sort(inventory.rbegin(), inventory.rend());
        int n = inventory.size();
        long long ans = 0, width = 1;
        for (int i = 0; i < n && orders > 0; ++i) {
            long long cur = inventory[i];
            long long nxt = (i + 1 < n) ? inventory[i + 1] : 0LL;
            if (cur == nxt) {
                ++width;
                continue;
            }
            long long band = (cur - nxt) * width;
            if (band >= orders) {
                long long full = orders / width, rem = orders % width;
                ans = (ans + width % MOD * seriesSum(cur, cur - full + 1)) % MOD;
                if (rem > 0) ans = (ans + rem % MOD * ((cur - full) % MOD)) % MOD;
                orders = 0;
            } else {
                ans = (ans + width % MOD * seriesSum(cur, nxt + 1)) % MOD;
                orders -= (int)band;
                ++width;
            }
        }
        return (int)ans;
    }
};

