    private long seriesSum(long hi, long lo) {
        long cnt = hi - lo + 1;
        long s = hi + lo;
        if (cnt % 2 == 0) cnt /= 2;
        else s /= 2;
        return cnt % MOD * (s % MOD) % MOD;
    }

    public int maxProfit(int[] inventory, int orders) {
        Arrays.sort(inventory);
        int n = inventory.length;
        long ans = 0, width = 1;
        for (int i = n - 1; i >= 0 && orders > 0; i--) {
            long cur = inventory[i];
            long nxt = (i > 0) ? inventory[i - 1] : 0L;
            if (cur == nxt) {
                width++;
                continue;
            }
            long band = (cur - nxt) * width;
            if (band >= orders) {
                long full = orders / width, rem = orders % width;
                ans = (ans + width % MOD * seriesSum(cur, cur - full + 1)) % MOD;
                if (rem > 0) ans = (ans + rem % MOD * ((cur - full) % MOD)) % MOD;
                orders = 0;
