var maxProfit = function(inventory, orders) {
    inventory.sort((a, b) => b - a);
    const MOD = 1000000007n;
    let ans = 0n;
    let width = 1n;
    const n = inventory.length;

    const seriesSum = (hi, lo) => {
        let cnt = hi - lo + 1n;
        let s = hi + lo;
        if (cnt % 2n === 0n) cnt /= 2n;
        else s /= 2n;
        return (cnt % MOD) * (s % MOD) % MOD;
    };

    for (let i = 0; i < n && orders > 0; i++) {
        const cur = BigInt(inventory[i]);
        const nxt = i + 1 < n ? BigInt(inventory[i + 1]) : 0n;
        if (cur === nxt) {
            width++;
            continue;
        }
        const band = (cur - nxt) * width;
        if (band >= BigInt(orders)) {
            const o = BigInt(orders);
            const full = o / width, rem = o % width;
            ans = (ans + width % MOD * seriesSum(cur, cur - full + 1n)) % MOD;
            if (rem > 0n) ans = (ans + rem % MOD * ((cur - full) % MOD)) % MOD;
            orders = 0;
        } else {
            ans = (ans + width % MOD * seriesSum(cur, nxt + 1n)) % MOD;
            orders -= Number(band);
            width++;
        }
    }
    return Number(ans);
};
